import { useRole } from "../context/RoleContext";
import { useNavigate } from "react-router-dom";

export default function RoleSelector() {
  const { setRole } = useRole();
  const navigate = useNavigate();

  const select = (role) => {
    setRole(role);
    navigate(role === "recruiter" ? "/job-setup" : "/hm-dashboard");
  };

  return (
    <div style={{
      minHeight: "100vh", background: "var(--navy)",
      display: "flex", alignItems: "center", justifyContent: "center",
      position: "relative", overflow: "hidden",
    }}>
      {/* Background glow effects */}
      <div style={{
        position: "absolute", top: "20%", left: "30%",
        width: 600, height: 600, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(59,130,246,0.06) 0%, transparent 70%)",
        pointerEvents: "none",
      }}/>
      <div style={{
        position: "absolute", bottom: "10%", right: "20%",
        width: 400, height: 400, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(20,184,166,0.05) 0%, transparent 70%)",
        pointerEvents: "none",
      }}/>

      <div style={{ textAlign: "center", animation: "fadeUp 0.6s ease forwards", position: "relative", zIndex: 1 }}>
        {/* Logo mark */}
        <div style={{
          width: 64, height: 64, borderRadius: 18,
          background: "linear-gradient(135deg, var(--blue), #6366F1)",
          display: "flex", alignItems: "center", justifyContent: "center",
          margin: "0 auto 32px",
          fontSize: 28, fontWeight: 800, fontFamily: "Plus Jakarta Sans",
          boxShadow: "0 0 40px rgba(59,130,246,0.3)",
        }}>P</div>

        <h1 style={{
          fontFamily: "Plus Jakarta Sans", fontWeight: 800,
          fontSize: 42, color: "var(--text-primary)",
          marginBottom: 12, lineHeight: 1.1,
        }}>
          Passive Talent Finder
        </h1>
        <p style={{
          color: "var(--text-secondary)", fontSize: 18,
          marginBottom: 8, fontWeight: 300,
        }}>
          Predictive AI for Headhunting
        </p>
        <p style={{
          color: "var(--text-muted)", fontSize: 14,
          marginBottom: 56,
        }}>
          Identify and rank passive talent from your CV dataset
        </p>

        {/* Role cards */}
        <div style={{ display: "flex", gap: 20, justifyContent: "center" }}>

          {/* Recruiter card */}
          <button onClick={() => select("recruiter")} style={{
            background: "var(--navy-2)", border: "1px solid var(--border)",
            borderRadius: 20, padding: "36px 40px", cursor: "pointer",
            width: 260, textAlign: "left", transition: "all 0.25s",
            animation: "fadeUp 0.6s ease 0.1s both",
          }}
          onMouseEnter={e => {
            e.currentTarget.style.borderColor = "var(--blue)";
            e.currentTarget.style.transform = "translateY(-4px)";
            e.currentTarget.style.boxShadow = "0 20px 40px rgba(59,130,246,0.15)";
          }}
          onMouseLeave={e => {
            e.currentTarget.style.borderColor = "var(--border)";
            e.currentTarget.style.transform = "translateY(0)";
            e.currentTarget.style.boxShadow = "none";
          }}>
            <div style={{
              width: 48, height: 48, borderRadius: 12,
              background: "rgba(59,130,246,0.15)",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 22, marginBottom: 20,
            }}>🔍</div>
            <div style={{
              fontFamily: "Plus Jakarta Sans", fontWeight: 700,
              fontSize: 18, color: "var(--text-primary)", marginBottom: 8,
            }}>Recruiter</div>
            <div style={{ color: "var(--text-secondary)", fontSize: 13, lineHeight: 1.6 }}>
              Upload CVs, run AI matching, and find the best passive candidates for your role.
            </div>
            <div style={{
              marginTop: 24, color: "var(--blue)", fontSize: 13,
              fontFamily: "Plus Jakarta Sans", fontWeight: 600,
              display: "flex", alignItems: "center", gap: 6,
            }}>
              Get started →
            </div>
          </button>

          {/* Hiring Manager card */}
          <button onClick={() => select("hiring_manager")} style={{
            background: "var(--navy-2)", border: "1px solid var(--border)",
            borderRadius: 20, padding: "36px 40px", cursor: "pointer",
            width: 260, textAlign: "left", transition: "all 0.25s",
            animation: "fadeUp 0.6s ease 0.2s both",
          }}
          onMouseEnter={e => {
            e.currentTarget.style.borderColor = "var(--teal)";
            e.currentTarget.style.transform = "translateY(-4px)";
            e.currentTarget.style.boxShadow = "0 20px 40px rgba(20,184,166,0.12)";
          }}
          onMouseLeave={e => {
            e.currentTarget.style.borderColor = "var(--border)";
            e.currentTarget.style.transform = "translateY(0)";
            e.currentTarget.style.boxShadow = "none";
          }}>
            <div style={{
              width: 48, height: 48, borderRadius: 12,
              background: "rgba(20,184,166,0.15)",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 22, marginBottom: 20,
            }}>📋</div>
            <div style={{
              fontFamily: "Plus Jakarta Sans", fontWeight: 700,
              fontSize: 18, color: "var(--text-primary)", marginBottom: 8,
            }}>Hiring Manager</div>
            <div style={{ color: "var(--text-secondary)", fontSize: 13, lineHeight: 1.6 }}>
              Review AI-ranked shortlists, approve candidates, and provide feedback to refine results.
            </div>
            <div style={{
              marginTop: 24, color: "var(--teal)", fontSize: 13,
              fontFamily: "Plus Jakarta Sans", fontWeight: 600,
              display: "flex", alignItems: "center", gap: 6,
            }}>
              Review shortlists →
            </div>
          </button>
        </div>

        {/* Bottom note */}
        <p style={{ color: "var(--text-muted)", fontSize: 12, marginTop: 40 }}>
          GUC Graduation Project · Predictive AI for Headhunting
        </p>
      </div>
    </div>
  );
}
